import { test, expect } from '@playwright/test';

test.describe('Form Data Persistence on Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <head>
          <title>Form Persistence Test</title>
          <script>
            function saveFormData() {
              const formData = {
                name: document.getElementById('name').value,
                email: document.getElementById('email').value,
                message: document.getElementById('message').value
              };
              localStorage.setItem('formData', JSON.stringify(formData));
            }

            function restoreFormData() {
              const saved = localStorage.getItem('formData');
              if (saved) {
                const formData = JSON.parse(saved);
                document.getElementById('name').value = formData.name || '';
                document.getElementById('email').value = formData.email || '';
                document.getElementById('message').value = formData.message || '';
              }
            }

            window.addEventListener('load', restoreFormData);
          </script>
        </head>
        <body>
          <h1>Contact Form</h1>
          <form id="contactForm">
            <div>
              <label for="name">Name:</label>
              <input type="text" id="name" name="name" onchange="saveFormData()" />
            </div>
            <div>
              <label for="email">Email:</label>
              <input type="email" id="email" name="email" onchange="saveFormData()" />
            </div>
            <div>
              <label for="message">Message:</label>
              <textarea id="message" name="message" onchange="saveFormData()"></textarea>
            </div>
            <button type="submit">Submit</button>
            <a href="other-page.html" id="navLink">Go to Other Page</a>
          </form>
        </body>
      </html>
    `);
  });

  test('should persist form data when user navigates away and returns', async ({ page }) => {
    // Fill in the form fields
    await page.getByLabel('Name:').fill('John Doe');
    await page.getByLabel('Email:').fill('john@example.com');
    await page.getByLabel('Message:').fill('This is a test message');

    // Trigger save by changing focus
    await page.getByLabel('Message:').blur();

    // Verify data is saved in localStorage
    const savedData = await page.evaluate(() => localStorage.getItem('formData'));
    expect(savedData).toBeTruthy();
    const parsedData = JSON.parse(savedData!);
    expect(parsedData.name).toBe('John Doe');
    expect(parsedData.email).toBe('john@example.com');
    expect(parsedData.message).toBe('This is a test message');

    // Simulate navigation away by reloading the page
    await page.reload();

    // Verify form data is restored after reload
    const nameValue = await page.getByLabel('Name:').inputValue();
    const emailValue = await page.getByLabel('Email:').inputValue();
    const messageValue = await page.getByLabel('Message:').inputValue();

    expect(nameValue).toBe('John Doe');
    expect(emailValue).toBe('john@example.com');
    expect(messageValue).toBe('This is a test message');
  });

  test('should persist partial form data when only some fields are filled', async ({ page }) => {
    // Fill only name and email, leave message empty
    await page.getByLabel('Name:').fill('Jane Smith');
    await page.getByLabel('Email:').fill('jane@example.com');

    // Trigger save
    await page.getByLabel('Email:').blur();

    // Reload the page
    await page.reload();

    // Verify partial data is restored correctly
    const nameValue = await page.getByLabel('Name:').inputValue();
    const emailValue = await page.getByLabel('Email:').inputValue();
    const messageValue = await page.getByLabel('Message:').inputValue();

    expect(nameValue).toBe('Jane Smith');
    expect(emailValue).toBe('jane@example.com');
    expect(messageValue).toBe('');
  });

  test('should update persisted data when form fields are modified', async ({ page }) => {
    // Initial fill
    await page.getByLabel('Name:').fill('Initial Name');
    await page.getByLabel('Name:').blur();

    // Verify initial data is saved
    let savedData = await page.evaluate(() => localStorage.getItem('formData'));
    let parsedData = JSON.parse(savedData!);
    expect(parsedData.name).toBe('Initial Name');

    // Modify the field
    await page.getByLabel('Name:').clear();
    await page.getByLabel('Name:').fill('Updated Name');
    await page.getByLabel('Name:').blur();

    // Verify updated data is saved
    savedData = await page.evaluate(() => localStorage.getItem('formData'));
    parsedData = JSON.parse(savedData!);
    expect(parsedData.name).toBe('Updated Name');

    // Reload and verify updated data persists
    await page.reload();
    const nameValue = await page.getByLabel('Name:').inputValue();
    expect(nameValue).toBe('Updated Name');
  });

  test('should clear persisted data when localStorage is cleared', async ({ page }) => {
    // Fill and save form data
    await page.getByLabel('Name:').fill('Test User');
    await page.getByLabel('Name:').blur();

    // Clear localStorage
    await page.evaluate(() => localStorage.clear());

    // Reload the page
    await page.reload();

    // Verify form fields are empty
    const nameValue = await page.getByLabel('Name:').inputValue();
    const emailValue = await page.getByLabel('Email:').inputValue();
    const messageValue = await page.getByLabel('Message:').inputValue();

    expect(nameValue).toBe('');
    expect(emailValue).toBe('');
    expect(messageValue).toBe('');
  });
});
